-- VIVA Directed Intake ("Talk it out" on /life-vision/start): each turn is one
-- VIVA prompt card plus the member's long-form reply. Replies are tagged into
-- vision_draft_session_notes (source = member) like every other passage, so
-- the depth gate and the compose pass see one body of material. Turns are the
-- audit trail and what the director reads as "the last thing they said".
-- Additive. NOTE: supabase/COMPLETE_SCHEMA_DUMP.sql is regenerated by the user.

CREATE TABLE IF NOT EXISTS public.vision_draft_session_turns (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  session_id uuid NOT NULL REFERENCES public.vision_draft_sessions (id) ON DELETE CASCADE,
  turn_index integer NOT NULL,
  prompt_text text NOT NULL,
  target_categories text[] NOT NULL DEFAULT '{}',
  member_text text NOT NULL,
  member_words integer NOT NULL DEFAULT 0,
  tagged_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (session_id, turn_index)
);

COMMENT ON TABLE public.vision_draft_session_turns IS
  'Directed intake turns: VIVA prompt + member long-form reply, per draft session.';
COMMENT ON COLUMN public.vision_draft_session_turns.target_categories IS
  'Life areas the prompt aimed at (core-four anchors first, then coverage gaps).';

CREATE INDEX IF NOT EXISTS idx_vision_draft_session_turns_session
  ON public.vision_draft_session_turns (session_id, turn_index);

ALTER TABLE public.vision_draft_session_turns ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "vision_draft_session_turns_owner_select"
  ON public.vision_draft_session_turns;
CREATE POLICY "vision_draft_session_turns_owner_select"
  ON public.vision_draft_session_turns FOR SELECT
  USING (
    EXISTS (
      SELECT 1 FROM public.vision_draft_sessions s
      WHERE s.id = session_id AND s.user_id = auth.uid()
    )
  );

DROP POLICY IF EXISTS "vision_draft_session_turns_owner_insert"
  ON public.vision_draft_session_turns;
CREATE POLICY "vision_draft_session_turns_owner_insert"
  ON public.vision_draft_session_turns FOR INSERT
  WITH CHECK (
    EXISTS (
      SELECT 1 FROM public.vision_draft_sessions s
      WHERE s.id = session_id AND s.user_id = auth.uid()
    )
  );

DROP POLICY IF EXISTS "vision_draft_session_turns_owner_update"
  ON public.vision_draft_session_turns;
CREATE POLICY "vision_draft_session_turns_owner_update"
  ON public.vision_draft_session_turns FOR UPDATE
  USING (
    EXISTS (
      SELECT 1 FROM public.vision_draft_sessions s
      WHERE s.id = session_id AND s.user_id = auth.uid()
    )
  )
  WITH CHECK (
    EXISTS (
      SELECT 1 FROM public.vision_draft_sessions s
      WHERE s.id = session_id AND s.user_id = auth.uid()
    )
  );

DROP POLICY IF EXISTS "vision_draft_session_turns_owner_delete"
  ON public.vision_draft_session_turns;
CREATE POLICY "vision_draft_session_turns_owner_delete"
  ON public.vision_draft_session_turns FOR DELETE
  USING (
    EXISTS (
      SELECT 1 FROM public.vision_draft_sessions s
      WHERE s.id = session_id AND s.user_id = auth.uid()
    )
  );

DROP POLICY IF EXISTS "vision_draft_session_turns_service_all"
  ON public.vision_draft_session_turns;
CREATE POLICY "vision_draft_session_turns_service_all"
  ON public.vision_draft_session_turns FOR ALL
  USING (auth.role() = 'service_role')
  WITH CHECK (auth.role() = 'service_role');
